/**
 * Single-file report bundler.
 *
 * Produces ONE self-contained .html containing both the dashboard and the
 * full findings list, with every screenshot embedded as a data: URI. No
 * sibling files, no shots/ folder, no server, no hosting — download the one
 * file, double-click it, and the whole report is there.
 *
 * Why this exists: the normal output is a folder (dashboard + report +
 * shots/). Azure DevOps serves pipeline artifacts as downloads, so getting to
 * the report meant fetching an archive and unpacking it; and a single file
 * pulled out of that archive rendered without its evidence images, because
 * the <img> paths are relative. A single file with the images inlined is
 * downloadable in one click and correct on its own.
 *
 * Merge notes (both documents are generated by lib/report.js, so this is
 * merging two known quantities, not arbitrary HTML):
 *   · The report markup uses no id attributes — verified — so there are no id
 *     collisions with the dashboard.
 *   · The report's own <script> is DROPPED. It selects '.filters button',
 *     which would also match the dashboard's filter buttons and hijack them.
 *     The controller written here drives both views instead.
 *   · The dashboard's script only selects '.fbtn' and its own tables, so it
 *     is kept as-is and never reaches into the findings view.
 */
const fs = require('fs');
const path = require('path');

const MIME = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.gif': 'image/gif', '.webp': 'image/webp' };

const styleOf = (html) => {
  const m = html.match(/<style>([\s\S]*?)<\/style>/);
  return m ? m[1] : '';
};
const bodyOf = (html) => {
  const m = html.match(/<body>([\s\S]*)<\/body>/);
  return m ? m[1] : html;
};
const titleOf = (html) => {
  const m = html.match(/<title>([\s\S]*?)<\/title>/);
  return m ? m[1] : 'Accessibility Report';
};

/**
 * Replace every relative <img src="..."> with a data: URI.
 * Looks for each referenced file across the supplied roots, first match wins.
 * Missing files are left untouched rather than blanked, so a broken path stays
 * visible as a broken image instead of silently disappearing.
 */
function inlineImages(html, roots, log = () => {}) {
  const cache = new Map();
  let embedded = 0, missing = 0, bytes = 0;

  const out = html.replace(/(<img\b[^>]*?\bsrc=")([^"]+)(")/g, (full, pre, src, post) => {
    if (/^(data:|https?:|\/\/)/i.test(src)) return full;
    if (cache.has(src)) { embedded++; return pre + cache.get(src) + post; }

    for (const root of roots) {
      const file = path.join(root, src);
      if (!fs.existsSync(file)) continue;
      try {
        const buf = fs.readFileSync(file);
        const uri = `data:${MIME[path.extname(file).toLowerCase()] || 'application/octet-stream'};base64,${buf.toString('base64')}`;
        cache.set(src, uri);
        embedded++; bytes += buf.length;
        return pre + uri + post;
      } catch (e) { /* fall through to the next root */ }
    }
    missing++;
    return full;
  });

  log(`   • inlined ${cache.size} unique image(s) across ${embedded} reference(s)`
    + `${missing ? `, ${missing} not found` : ''} (${(bytes / 1e6).toFixed(1)} MB before encoding)`);
  return out;
}

/** The view switcher + findings filtering, replacing the report's own script. */
const CONTROLLER = `<script>
(function(){
  var views = { summary: document.getElementById('view-summary'),
                plan: document.getElementById('view-plan'),
                findings: document.getElementById('view-findings') };
  var tabs = [].slice.call(document.querySelectorAll('[data-view]'));
  var issues = [].slice.call(document.querySelectorAll('#view-findings .issue'));
  var banner = document.getElementById('scopeBanner');
  var scope = null;     // {page, state} from a dashboard deep-link, or null
  var status = 'all';

  function show(name){
    Object.keys(views).forEach(function(k){ if(views[k]) views[k].hidden = (k !== name); });
    tabs.forEach(function(t){ t.classList.toggle('on', t.dataset.view === name); });
    window.scrollTo(0, 0);
  }

  function inScope(el){
    if (!scope) return true;
    if (scope.page && el.dataset.page !== scope.page) return false;
    if (scope.state) {
      try { return JSON.parse(el.dataset.states || '[]').indexOf(scope.state) !== -1; }
      catch (e) { return false; }
    }
    return true;
  }
  function matchesStatus(el){
    return status === 'all' || el.dataset.impact === status || el.dataset.kind === status;
  }
  function apply(){
    var shown = 0;
    issues.forEach(function(el){
      var ok = inScope(el) && matchesStatus(el);
      el.style.display = ok ? '' : 'none';
      if (ok) shown++;
    });
    if (banner) {
      if (scope) {
        var bits = [];
        if (scope.page)  bits.push('page \\u201C' + scope.page + '\\u201D');
        if (scope.state) bits.push('state \\u201C' + scope.state + '\\u201D');
        banner.innerHTML = '<b>Filtered</b> to ' + bits.join(' \\u00B7 ') + ' \\u2014 ' + shown
          + ' finding(s). <a href="#" id="clearScope">Show all</a>';
        banner.hidden = false;
        var c = document.getElementById('clearScope');
        if (c) c.onclick = function(e){ e.preventDefault(); scope = null; apply(); };
      } else {
        banner.hidden = true;
      }
    }
  }

  tabs.forEach(function(t){
    t.addEventListener('click', function(e){ e.preventDefault(); show(t.dataset.view); });
  });

  // Dashboard deep-links ("… ?page=X&state=Y") are rewritten at bundle time
  // into data attributes; they switch view and scope the list.
  document.querySelectorAll('a[data-deeplink]').forEach(function(a){
    a.addEventListener('click', function(e){
      e.preventDefault();
      scope = (a.dataset.page || a.dataset.state)
        ? { page: a.dataset.page || '', state: a.dataset.state || '' } : null;
      status = 'all';
      document.querySelectorAll('#view-findings .filters button').forEach(function(b){
        b.classList.toggle('active', b.dataset.f === 'all');
      });
      apply(); show('findings');
    });
  });

  document.querySelectorAll('#view-findings .filters button').forEach(function(b){
    b.addEventListener('click', function(){
      document.querySelectorAll('#view-findings .filters button')
        .forEach(function(x){ x.classList.remove('active'); });
      b.classList.add('active');
      status = b.dataset.f;
      apply();
    });
  });

  apply();
  show('summary');
})();
</script>`;

const TAB_CSS = `
.bundle-tabs{display:flex;gap:8px;margin:0 0 18px}
.bundle-tabs a{display:inline-block;padding:8px 16px;border:1px solid #d3d9e2;border-radius:8px;
  color:#374151;background:#fff;font-size:13px;text-decoration:none;cursor:pointer}
.bundle-tabs a.on{background:#111827;border-color:#111827;color:#fff}
.bundle-note{color:#5b6472;font-size:12px;margin:0 0 18px}
#scopeBanner{background:#eef4fb;border:1px solid #cddffb;border-radius:8px;padding:10px 14px;
  margin:0 0 14px;font-size:13px}
@media print{.bundle-tabs{display:none}[hidden]{display:block !important}}
`;

/**
 * @param {string} outDir      where to write the bundle
 * @param {object} html        { dashboard, report, plan? } — generated HTML strings;
 *                             plan is renderFixPlan(..., {mode:'bundle'}) → {body, css}
 * @param {object} opts        { shotRoots: string[], file, log }
 * @returns {{file:string, bytes:number}}
 */
function writeSingleFile(outDir, html, opts = {}) {
  const log = opts.log || (() => {});
  const file = path.join(outDir, opts.file || 'accessibility-report.html');

  let dash = bodyOf(html.dashboard);
  let rep = bodyOf(html.report);

  // Cross-document links become in-page view switches.
  //   all-pages-report.html?page=X&state=Y  ->  data-deeplink + data-page/state
  dash = dash.replace(/<a href="[^"]*report\.html\?([^"]*)"/g, (full, qs) => {
    const p = new URLSearchParams(qs.replace(/&amp;/g, '&'));
    const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
    return `<a href="#findings" data-deeplink data-page="${esc(p.get('page'))}" data-state="${esc(p.get('state'))}"`;
  });
  dash = dash.replace(/<a href="[^"]*report\.html"/g, '<a href="#findings" data-deeplink');
  rep = rep.replace(/<a href="[^"]*dashboard\.html"/g, '<a href="#summary" data-view="summary"');
  // The fix plan is a tab here when it was passed in; otherwise drop links to a file that isn't there.
  const planTab = html.plan && html.plan.body;
  dash = dash.replace(/<a href="[^"]*fix-plan\.html"([^>]*)>([\s\S]*?)<\/a>/g, (full, attrs, text) => (planTab
    ? `<a href="#plan" data-view="plan"${attrs}>${text}</a>`
    : ''));

  // Drop the report's own script — it would capture the dashboard's filter
  // buttons via '.filters button'. CONTROLLER takes over both views.
  const before = (rep.match(/<script>/g) || []).length;
  rep = rep.replace(/<script>[\s\S]*?<\/script>/g, '');
  log(`   • removed ${before} inline script(s) from the findings view (superseded by the bundle controller)`);

  // Screenshots -> data: URIs. Only the findings view carries images.
  const roots = opts.shotRoots || [outDir];
  rep = inlineImages(rep, roots, log);

  const styles = styleOf(html.dashboard);
  const repStyles = styleOf(html.report);
  const extra = repStyles && repStyles !== styles ? repStyles : '';

  const doc = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${titleOf(html.dashboard)}</title>
<style>${styles}${extra}${TAB_CSS}${planTab ? html.plan.css : ''}</style></head><body>
<div class="wrap" style="padding-bottom:0">
  <nav class="bundle-tabs">
    <a href="#summary"  data-view="summary" class="on">Dashboard</a>
    ${planTab ? '<a href="#plan" data-view="plan">Fix plan</a>' : ''}
    <a href="#findings" data-view="findings">All findings</a>
  </nav>
  <p class="bundle-note">Single-file report — screenshots are embedded, so this file works on its own with no other files, no server and no network.</p>
  <div id="scopeBanner" hidden></div>
</div>
<div id="view-summary">${dash}</div>
${planTab ? `<div id="view-plan" hidden>${html.plan.body}</div>` : ''}
<div id="view-findings" hidden>${rep}</div>
${CONTROLLER}
</body></html>`;

  fs.writeFileSync(file, doc);
  const bytes = Buffer.byteLength(doc);
  log(`   • single-file report: ${(bytes / 1e6).toFixed(1)} MB → ${path.basename(file)}`);
  return { file, bytes };
}

module.exports = { writeSingleFile, inlineImages };
